package com.ruoyi.kangaroo.ext.operations;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.kangaroo.ext.KgJdbc.p;
import static com.ruoyi.kangaroo.ext.operations.OpsRules.*;
import java.util.*;
import java.util.concurrent.*;
import com.alibaba.fastjson2.JSON;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.kangaroo.security.admin.AdminCityContext;
import org.springframework.test.util.ReflectionTestUtils;

class OperationsEditingDatabaseTest extends OperationsReminderDatabaseTest {
    OpsForms forms;OpsDailyChanges changes;
    @BeforeEach void editing(){forms=(OpsForms)ReflectionTestUtils.getField(daily,"forms");changes=new OpsDailyChanges();wire(changes,"db",db,"scope",scope,"daily",daily);}
    Map<String,Object> open(){return tx.execute(s->daily.open(KEEPER,CITY,"keeper","2026-11-15"));}
    Map<String,Object> values(){return p("tomorrowPlan","明日跟进入住","facilities","无","shortages","无","yesterdayIssues","无","activityPlan","明日徒步","activityNote","","offlineIncome","10.10","expenses",Arrays.asList(p("date","2026-11-15","item","纸巾","handler","测试人","amount","2.30")),"remedies",p());}
    Map<String,Object> submit(){Map<String,Object> r=open();return tx.execute(s->daily.save(KEEPER,number(r.get("reportId")),p("revision",r.get("revision"),"manual",values()),true));}
    Map<String,Object> correction(Map<String,Object> r){Map<String,Object> v=new LinkedHashMap<>((Map<String,Object>)r.get("manual"));v.put("tomorrowPlan","明日回访客人");return p("requestId",UUID.randomUUID().toString(),"revision",r.get("revision"),"manual",v,"reason","根据已确认安排更正");}
    Map<String,Object> formBody(String role){Map<String,Object> form=forms.current(role);form.put("reason","调整每日填写项目");return form;}
    Map<String,Object> custom(){return p("key","custom_followup01","label","今日回访","type","textarea","enabled",true,"required",true,"maxLength",100,"placeholder","记录回访进展");}
    @Test void correctionPreservesSubmittedStateAutoSnapshotAndAudit(){
        Map<String,Object> r=submit();long id=number(r.get("reportId"));String auto=JSON.toJSONString(r.get("auto")),submitted=text(r.get("submittedAt"));Map<String,Object> body=correction(r);
        AdminCityContext.set(Arrays.asList(CITY));Map<String,Object> saved=tx.execute(s->changes.save(id,body,71,"城市管理员"));assertEquals("submitted",saved.get("status"));assertEquals(submitted,text(saved.get("submittedAt")));assertEquals(auto,JSON.toJSONString(saved.get("auto")));assertEquals(number(r.get("revision"))+1,number(saved.get("revision")));
        assertEquals(1,changes.history(id).size());assertTrue(text(changes.history(id).get(0).get("beforeJson")).contains("明日跟进入住"));assertTrue(text(changes.history(id).get(0).get("afterJson")).contains("明日回访客人"));
        tx.execute(s->changes.save(id,body,71,"城市管理员"));assertEquals(1,changes.history(id).size());AdminCityContext.clear();assertTrue(text(daily.get(KEEPER,id).get("summaryText")).contains("明日回访客人"));assertEquals(1,changes.forUser(KEEPER,id).size());assertThrows(ServiceException.class,()->changes.forUser(STRANGER,id));
        assertTrue(new OpsExport().rows(daily.adminGet(id)).toString().contains("根据已确认安排更正"));
    }
    @Test void correctionCannotCrossCityOrReadOtherHistory(){Map<String,Object> r=submit();long id=number(r.get("reportId"));AdminCityContext.set(Arrays.asList(OTHER));assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,correction(r),71,"其他城市")));assertThrows(ServiceException.class,()->changes.history(id));AdminCityContext.clear();assertEquals(0,changes.history(id).size());}
    @Test void staleDraftCannotOverwriteAdminCorrectionAndDraftStaysUnsubmitted(){Map<String,Object> r=open();long id=number(r.get("reportId"));tx.execute(s->changes.save(id,correction(r),1,"平台管理员"));assertEquals("draft",daily.get(KEEPER,id).get("status"));assertThrows(ServiceException.class,()->tx.execute(s->daily.save(KEEPER,id,p("revision",r.get("revision"),"manual",values()),false)));}
    @Test void correctionValidatesReasonRequiredFieldsAndExpenseDates(){Map<String,Object> r=submit();long id=number(r.get("reportId"));Map<String,Object> body=correction(r);body.put("reason","");assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,body,1,"管理员")));body.put("reason","更正");((Map)body.get("manual")).put("tomorrowPlan","");assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,body,1,"管理员")));((Map)body.get("manual")).put("tomorrowPlan","明日回访");((Map)body.get("manual")).put("expenses",Arrays.asList(p("date","2026-11-20","item","采购","handler","测试","amount","10")));assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,body,1,"管理员")));assertEquals(0,changes.history(id).size());}
    @Test void correctionCannotReuseRequestForDifferentActorOrPayload(){Map<String,Object> r=submit();long id=number(r.get("reportId"));Map<String,Object> b=correction(r);tx.execute(s->changes.save(id,b,1,"管理员"));assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,b,2,"另一个管理员")));b.put("reason","不同原因");assertThrows(ServiceException.class,()->tx.execute(s->changes.save(id,b,1,"管理员")));assertEquals(1,changes.history(id).size());}
    @Test void concurrentCorrectionRetryHasOneAuditAndOneRevision()throws Exception{Map<String,Object> r=submit();long id=number(r.get("reportId"));Map<String,Object> b=correction(r);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Map<String,Object>> a=pool.submit(()->tx.execute(s->changes.save(id,b,1,"管理员"))),c=pool.submit(()->tx.execute(s->changes.save(id,b,1,"管理员")));assertEquals(a.get(15,TimeUnit.SECONDS).get("revision"),c.get(15,TimeUnit.SECONDS).get("revision"));assertEquals(1,changes.history(id).size());}finally{pool.shutdownNow();}}
    @Test void formsApplyToNewReportsButNeverRewriteExistingDraft(){Map<String,Object> old=open(),b=formBody("keeper");OpsForms.fields(b).add(custom());Map<String,Object> saved=tx.execute(s->forms.save("keeper",b,1,"管理员"));assertEquals(1L,number(saved.get("revision")));assertEquals(1,forms.history("keeper").size());assertEquals(0L,number(((Map)daily.get(KEEPER,number(old.get("reportId"))).get("form")).get("revision")));at("2026-11-16T18:10:00");Map<String,Object> fresh=tx.execute(s->daily.open(KEEPER,CITY,"keeper","2026-11-16"));assertEquals(1L,number(((Map)fresh.get("form")).get("revision")));Map<String,Object> v=values();v.put("expenses",Collections.emptyList());assertThrows(ServiceException.class,()->tx.execute(s->daily.save(KEEPER,number(fresh.get("reportId")),p("revision",fresh.get("revision"),"manual",v),true)));v.put("custom_followup01","已回访三人");Map<String,Object> finalRow=tx.execute(s->daily.save(KEEPER,number(fresh.get("reportId")),p("revision",fresh.get("revision"),"manual",v),true));assertTrue(text(finalRow.get("summaryText")).contains("已回访三人"));assertTrue(new OpsExport().rows(finalRow).toString().contains("今日回访"));}
    @Test void formRenameOptionalHiddenOrderAndNumericFieldsWork(){Map<String,Object> b=formBody("keeper");for(Map<String,Object> f:OpsForms.fields(b)){if("tomorrowPlan".equals(f.get("key"))){f.put("label","明日安排");f.put("required",false);}if("facilities".equals(f.get("key")))f.put("enabled",false);}Map<String,Object> custom=custom();custom.put("type","number");OpsForms.fields(b).add(0,custom);tx.execute(s->forms.save("keeper",b,1,"管理员"));Map<String,Object> r=open(),v=values();v.put("tomorrowPlan","");v.put("facilities","");v.put("custom_followup01","abc");assertThrows(ServiceException.class,()->tx.execute(s->daily.save(KEEPER,number(r.get("reportId")),p("revision",r.get("revision"),"manual",v),true)));v.put("custom_followup01","2.50");Map<String,Object> finalRow=tx.execute(s->daily.save(KEEPER,number(r.get("reportId")),p("revision",r.get("revision"),"manual",v),true));assertEquals("2.5",((Map)finalRow.get("manual")).get("custom_followup01"));assertEquals("custom_followup01",OpsForms.fields((Map<String,Object>)finalRow.get("form")).get(0).get("key"));}
    @Test void limitedAdminCannotChangeRoleWideFormAndReadOnlySqlGuardProtectsIt(){Map<String,Object> b=formBody("manager");AdminCityContext.set(Arrays.asList(CITY));assertNotNull(forms.current("manager"));assertThrows(ServiceException.class,()->tx.execute(s->forms.save("manager",b,9,"城市管理员")));assertThrows(ServiceException.class,()->db.update("update kg_ops_form set revision=2 where role_code='manager'",p()));AdminCityContext.clear();assertEquals(0L,number(forms.current("manager").get("revision")));}
    @Test void formValidatesStableKeysDuplicatesAndConflictingVersion(){Map<String,Object> b=formBody("manager");OpsForms.fields(b).add(custom());tx.execute(s->forms.save("manager",b,1,"管理员"));assertThrows(ServiceException.class,()->tx.execute(s->forms.save("manager",b,1,"管理员")));Map<String,Object> bad=formBody("manager");OpsForms.fields(bad).add(custom());assertThrows(ServiceException.class,()->tx.execute(s->forms.save("manager",bad,1,"管理员")));final Map<String,Object> removed=formBody("manager");OpsForms.fields(removed).remove(0);assertThrows(ServiceException.class,()->tx.execute(s->forms.save("manager",removed,1,"管理员")));assertEquals(1,forms.history("manager").size());}
    @Test void existingLegacyReportUsesDefaultFieldsEvenAfterTemplateChanges(){Map<String,Object> r=open();long id=number(r.get("reportId"));db.update("update kg_ops_daily set form_json=null where report_id=:id",p("id",id));Map<String,Object> b=formBody("keeper");OpsForms.fields(b).add(custom());tx.execute(s->forms.save("keeper",b,1,"管理员"));assertEquals(0L,number(((Map)daily.get(KEEPER,id).get("form")).get("revision")));assertEquals("submitted",tx.execute(s->daily.save(KEEPER,id,p("revision",r.get("revision"),"manual",values()),true)).get("status"));}
}
